'use strict';
(()=>{
  ui.s80SupplyMode=ui.s80SupplyMode||'list';
  ui.s80SupplyTab=ui.s80SupplyTab||'stock';
  ui.s80SupplyFilter=ui.s80SupplyFilter||'all';
  const a=value=>Array.isArray(value)?value:[];
  const qty=part=>a(part.locations).filter(location=>location.active!==false).reduce((sum,location)=>sum+Number(location.onHand||0),0);
  const low=part=>qty(part)<Number(part.min||0),out=part=>qty(part)<=0;
  const businesses=()=>[...a(state.businesses),...a(state.vendors)].filter((business,index,all)=>all.findIndex(other=>other.id===business.id||other.name===business.name)===index);
  const business=id=>businesses().find(item=>item.id===id||item.sourceVendorId===id);
  const supplier=part=>business(part.preferredBusinessId||part.businessId||part.vendorId);
  const storeName=id=>(typeof getStore==='function'&&getStore(id)?.name)||id||'Unassigned';
  const status=part=>out(part)?['Stocked out','out']:low(part)?['Below minimum','low']:['In stock','good'];
  const boxIcon=()=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 8 4.5v9L12 21l-8-4.5v-9L12 3Z"/><path d="m4.5 7.7 7.5 4.2 7.5-4.2M12 12v8.4"/></svg>';
  const badge=part=>{const item=status(part);return '<span class="s80-status '+item[1]+'"><i></i>'+item[0]+'</span>'};
  const searchText=part=>[part.code,part.name,part.description,part.category,part.barcode,part.manufacturer,part.model,supplier(part)?.name].join(' ').toLowerCase();

  function filterButton(id,label,count){return '<button class="'+(ui.s80SupplyFilter===id?'active':'')+'" data-s80-filter="'+id+'">'+label+' <b>'+count+'</b></button>'}
  function partRow(part){
    const locations=a(part.locations).filter(location=>location.active!==false).length;
    return '<tr data-s80-part-row data-s80-open-part="'+esc(part.id)+'" data-search="'+esc(searchText(part))+'" data-category="'+esc(part.category||'')+'"><td class="s80-check"><input type="checkbox" aria-label="Select '+esc(part.name)+'" onclick="event.stopPropagation()"></td><td><div class="s80-part-cell"><span>'+boxIcon()+'</span><div><strong>'+esc(part.name)+'</strong><small>'+esc(part.code)+' · '+esc(part.uom||'ea')+'</small></div></div></td><td>'+esc(part.category||'Uncategorized')+'</td><td><strong>'+qty(part)+' '+esc(part.uom||'')+'</strong></td><td>'+Number(part.min||0)+'</td><td>'+Number(part.max||0)+'</td><td>'+locations+'</td><td>'+money(Number(part.lastPrice||part.unitCost||0))+'</td><td>'+badge(part)+'</td><td class="s80-row-open">›</td></tr>';
  }
  function listPage(){
    const parts=a(state.parts),filter=ui.s80SupplyFilter,visible=parts.filter(part=>filter==='all'||filter==='low'&&low(part)||filter==='out'&&out(part)||filter==='healthy'&&!low(part));
    const categories=[...new Set(parts.map(part=>part.category).filter(Boolean))].sort();
    return '<div class="s80-page s80-list-page"><header class="s80-titlebar"><div><span>Supplies</span><h1>Parts and supplies</h1><p>Search, open and maintain the items used by your maintenance team.</p></div><div class="s80-title-actions"><button class="s80-btn" data-route="batch-stock">Batch stock adjustment</button><button class="s80-btn s80-primary" data-action="add-part">＋ New part / supply</button></div></header><section class="s80-commandbar"><button class="s80-command active">Parts list</button><button class="s80-command" data-route="stock-locations">Current stock</button><button class="s80-command" data-route="transactions">Stock history</button><span></span><button class="s80-icon-command" data-s80-refresh aria-label="Refresh parts list">↻</button></section><section class="s80-list-panel"><div class="s80-list-tools"><label class="s80-list-search"><span>⌕</span><input data-s80-list-search placeholder="Search part name, code, barcode, make or model" value="'+esc(ui.inventorySearch||'')+'"></label><label>Category<select data-s80-category><option value="">All categories</option>'+categories.map(category=>'<option>'+esc(category)+'</option>').join('')+'</select></label><div class="s80-filterset">'+filterButton('all','All',parts.length)+filterButton('low','Below min',parts.filter(low).length)+filterButton('out','Stocked out',parts.filter(out).length)+filterButton('healthy','In stock',parts.filter(part=>!low(part)).length)+'</div></div><div class="s80-table-shell"><table class="s80-list-table"><thead><tr><th class="s80-check"><input type="checkbox" aria-label="Select all parts"></th><th>Part / supply</th><th>Category</th><th>On hand</th><th>Min</th><th>Max</th><th>Locations</th><th>Last price</th><th>Status</th><th></th></tr></thead><tbody>'+visible.map(partRow).join('')+'</tbody></table><div class="s80-no-results" data-s80-no-results hidden><strong>No matching parts or supplies</strong><span>Change the search, category or stock filter.</span></div></div><footer class="s80-list-footer"><span data-s80-visible-count>'+visible.length+'</span> of '+parts.length+' records <b>·</b> Select a row to open its complete record.</footer></section></div>';
  }

  const input=(label,name,value,type='text')=>'<label><span>'+label+'</span><input name="'+name+'" type="'+type+'" '+(type==='number'?'min="0" step="0.01" ':'')+'value="'+esc(value)+'"></label>';
  const receipts=part=>a(state.stockTransactions).filter(tx=>tx.partId===part.id&&/receipt|receive/i.test(tx.type||'')).sort((x,y)=>String(y.at||'').localeCompare(String(x.at||'')));
  function receiptTable(part,limit=999){const rows=receipts(part).slice(0,limit);return '<div class="s80-data-table"><table><thead><tr><th>Date received</th><th>Receipt / reference</th><th>Qty received</th><th>Location</th><th>Received by</th></tr></thead><tbody>'+rows.map(tx=>'<tr><td>'+dateTimeFmt(tx.at)+'</td><td><strong>'+esc(tx.reference||tx.id||'Receipt')+'</strong></td><td>+'+Number(tx.qty||0)+' '+esc(part.uom||'')+'</td><td>'+esc(storeName(tx.storeId))+' · '+esc(tx.bin||'No bin')+'</td><td>'+esc(typeof getUser==='function'?(getUser(tx.userId)?.name||'System'):'System')+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="5" class="s80-empty-cell">No receipts have been recorded.</td></tr>')+'</tbody></table></div>'}
  const section=(title,description,actions,content)=>'<section class="s80-record-section s80-single-section"><header><div><h2>'+title+'</h2><p>'+description+'</p></div>'+actions+'</header>'+content+'</section>';
  function stockTab(part){
    const supplierId=part.preferredBusinessId||part.businessId||part.vendorId||'';
    return '<div class="s80-stock-grid"><section class="s80-record-section"><header><div><h2>Stock levels per location</h2><p>Click a row to edit its locator, quantities and active status.</p></div><button type="button" class="s80-mini-primary" data-v66-add-location="'+esc(part.id)+'">＋ Add</button></header><div class="s80-data-table"><table><thead><tr><th>Status</th><th>Location</th><th>Aisle</th><th>Row</th><th>Bin</th><th>Qty on hand</th><th>Min qty</th><th>Max qty</th><th></th></tr></thead><tbody>'+a(part.locations).map((location,index)=>'<tr data-v66-open-location="'+esc(part.id)+'|'+index+'"><td><span class="s80-dot '+(location.active===false?'inactive':'')+'"></span></td><td><strong>'+esc(storeName(location.storeId))+'</strong></td><td>'+esc(location.aisle||'—')+'</td><td>'+esc(location.row||'—')+'</td><td>'+esc(location.bin||'—')+'</td><td><strong>'+Number(location.onHand||0)+'</strong></td><td>'+Number(location.min||0)+'</td><td>'+Number(location.max||0)+'</td><td>›</td></tr>').join('')+(a(part.locations).length?'':'<tr><td colspan="9" class="s80-empty-cell">No locations are attached to this part.</td></tr>')+'</tbody></table></div><button type="button" class="s80-table-add" data-v66-add-location="'+esc(part.id)+'">＋</button></section><aside class="s80-stock-fields"><h2>Stock information</h2>'+input('Account','account',part.account||'')+input('Charge department','chargeDepartment',part.chargeDepartment||'')+input('Inventory code','inventoryCode',part.inventoryCode||part.code||'')+input('UNSPSC code','unspscCode',part.unspscCode||'')+input('Barcode','barcode',part.barcode||'')+input('Make','manufacturer',part.manufacturer||'')+input('Model','model',part.model||'')+input('Last price','lastPrice',Number(part.lastPrice||part.unitCost||0),'number')+'<label><span>Preferred supplier</span><select name="preferredBusinessId"><option value="">Not assigned</option>'+businesses().map(item=>'<option value="'+esc(item.id)+'" '+(item.id===supplierId?'selected':'')+'>'+esc(item.name)+'</option>').join('')+'</select></label><label class="s80-field-wide"><span>Notes</span><textarea name="notes" rows="4">'+esc(part.notes||'')+'</textarea></label><div class="s80-total-stock"><span>Total stock</span><strong>'+qty(part)+' '+esc(part.uom||'ea')+'</strong></div></aside></div><section class="s80-record-section s80-receipt-preview"><header><div><h2>Recent receipts</h2><p>Latest delivered quantities for this item.</p></div><button type="button" class="s80-mini" data-s80-tab="receipts">View all receipts</button></header>'+receiptTable(part,4)+'</section>';
  }
  function countsTab(part){const rows=a(state.cycleCounts).filter(item=>item.partId===part.id).sort((x,y)=>String(y.at||y.countedAt||'').localeCompare(String(x.at||x.countedAt||'')));return section('Cycle Count','Compare physical quantities with the system quantity.','<button type="button" class="s80-mini-primary" data-count-part="'+esc(part.id)+'">＋ New count</button>','<div class="s80-data-table"><table><thead><tr><th>Count</th><th>Date</th><th>Location</th><th>Expected</th><th>Counted</th><th>Variance</th><th>Counted by</th></tr></thead><tbody>'+rows.map(item=>'<tr><td><strong>'+esc(item.id)+'</strong></td><td>'+dateTimeFmt(item.at||item.countedAt)+'</td><td>'+esc(storeName(item.storeId))+' · '+esc(item.bin||'No bin')+'</td><td>'+Number(item.expected||0)+'</td><td>'+Number(item.counted||0)+'</td><td><span class="s80-variance '+(Number(item.variance||0)===0?'good':'')+'">'+(Number(item.variance||0)>0?'+':'')+Number(item.variance||0)+'</span></td><td>'+esc(typeof getUser==='function'?(getUser(item.userId)?.name||'System'):'System')+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="7" class="s80-empty-cell">No cycle counts recorded.</td></tr>')+'</tbody></table></div>')}
  function bomsTab(part){const rows=a(state.assets).filter(asset=>a(asset.bom).includes(part.id));return section('BOMs','Assets that use this part or supply.','<button type="button" class="s80-mini" data-route="assets">Asset hierarchy</button>','<div class="s80-data-table"><table><thead><tr><th>Asset code</th><th>Asset</th><th>Type</th><th>Standard quantity</th><th></th></tr></thead><tbody>'+rows.map(asset=>'<tr data-v66-open-asset="'+esc(asset.id)+'"><td><strong>'+esc(asset.code)+'</strong></td><td>'+esc(asset.name)+'</td><td>'+esc(asset.type||'Equipment')+'</td><td>'+Number(asset.bomQuantities?.[part.id]||1)+' '+esc(part.uom||'ea')+'</td><td>›</td></tr>').join('')+(rows.length?'':'<tr><td colspan="5" class="s80-empty-cell">This part is not linked to an asset BOM.</td></tr>')+'</tbody></table></div>')}
  function businessesTab(part){const selected=supplier(part),rows=businesses();return section('Businesses','Suppliers and manufacturers connected to this record.','<button type="button" class="s80-mini-primary" data-route="businesses">Business directory</button>','<div class="s80-business-list">'+rows.map(item=>'<article class="'+(selected?.id===item.id?'preferred':'')+'"><span>'+esc((item.name||'?').split(/\s+/).map(word=>word[0]).join('').slice(0,2))+'</span><div><small>'+(selected?.id===item.id?'Preferred supplier':esc(item.type||item.group||'Supplier'))+'</small><strong>'+esc(item.name)+'</strong><p>'+esc(item.contact||'No contact')+' · '+esc(item.phone||'No phone')+'</p><a href="mailto:'+esc(item.email||'')+'">'+esc(item.email||'No email')+'</a></div></article>').join('')+'</div>')}
  function receiptsTab(part){return section('Receipts','Delivered stock recorded for this item.','<button type="button" class="s80-mini" data-stock-move="'+esc(part.id)+'">Receive stock</button>',receiptTable(part))}
  function filesTab(part){return section('Files','Manuals, photographs, specifications and certificates.','','<label class="s80-file-drop"><strong>＋ Add files</strong><span>Choose files to attach to this part record.</span><input type="file" multiple data-s80-part-file="'+esc(part.id)+'" hidden></label><div class="attachment-list" data-s80-part-file-list="'+esc(part.id)+'"></div>')}
  function customTab(part){const fields=Object.entries(part.customFields||{});return section('Custom','Organization-specific information for this item.','<button type="button" class="s80-mini-primary" data-s79-edit-custom="'+esc(part.id)+'">Edit custom fields</button>','<div class="s80-custom-grid">'+(fields.length?fields.map(([key,value])=>'<div><span>'+esc(key)+'</span><strong>'+esc(value)+'</strong></div>').join(''):'<p>No custom fields have been added.</p>')+'</div>')}
  function historyTab(part){const rows=a(state.stockTransactions).filter(item=>item.partId===part.id).sort((x,y)=>String(y.at||'').localeCompare(String(x.at||'')));return section('Log','Auditable receipts, issues, transfers, adjustments and counts.','','<div class="s80-data-table"><table><thead><tr><th>Date</th><th>Movement</th><th>Location</th><th>Quantity</th><th>Before</th><th>After</th><th>Reference</th><th>User</th></tr></thead><tbody>'+rows.map(item=>'<tr><td>'+dateTimeFmt(item.at)+'</td><td>'+esc(item.type||'Movement')+'</td><td>'+esc(storeName(item.storeId))+' · '+esc(item.bin||'No bin')+'</td><td><strong>'+(Number(item.qty||0)>0?'+':'')+Number(item.qty||0)+' '+esc(part.uom||'')+'</strong></td><td>'+(item.qtyBefore??'—')+'</td><td>'+(item.qtyAfter??'—')+'</td><td>'+esc(item.reference||item.workOrderId||'—')+'</td><td>'+esc(typeof getUser==='function'?(getUser(item.userId)?.name||'System'):'System')+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="8" class="s80-empty-cell">No stock history exists for this part.</td></tr>')+'</tbody></table></div>')}
  const tabContent=part=>({stock:stockTab,counts:countsTab,boms:bomsTab,businesses:businessesTab,receipts:receiptsTab,files:filesTab,custom:customTab,history:historyTab}[ui.s80SupplyTab]||stockTab)(part);

  function recordPage(part){
    if(!part){ui.s80SupplyMode='list';return listPage()}
    const qr=window.SafiQR?SafiQR.svg('SM:P:'+part.id+':'+part.code,part.code):'',tabs=[['stock','Stock'],['counts','Cycle Count'],['boms','BOMs'],['businesses','Businesses'],['receipts','Receipts'],['files','Files'],['custom','Custom'],['history','Log']];
    return '<div class="s80-page s80-record-page"><header class="s80-record-actions"><button class="s80-back" data-s80-back>← <span>Back to parts</span></button><button class="s80-btn s80-primary" data-s80-save="'+esc(part.id)+'">Save</button><button class="s80-btn" data-s80-save-close="'+esc(part.id)+'">Save and close</button><button class="s80-btn" data-s80-print="'+esc(part.id)+'">Print tag</button><details class="s80-more"><summary>More⌄</summary><div><button data-stock-move="'+esc(part.id)+'">Transfer stock</button><button data-count-part="'+esc(part.id)+'">New cycle count</button><button data-s80-duplicate="'+esc(part.id)+'">Duplicate part</button></div></details></header><form class="s80-record" data-s80-record-form="'+esc(part.id)+'" onsubmit="return false"><section class="s80-record-heading"><div class="s80-part-photo">'+boxIcon()+'<button type="button" title="Add item image">＋</button></div><div class="s80-record-core"><label class="s80-name-field"><span>Part / supply name</span><input name="name" value="'+esc(part.name)+'" required></label><label class="s80-description-field"><span>Description</span><textarea name="description" rows="2" placeholder="Identification details for technicians">'+esc(part.description||'')+'</textarea></label><div class="s80-core-row"><label><span>Code</span><input name="code" value="'+esc(part.code)+'" required></label><label><span>Category</span><input name="category" value="'+esc(part.category||'')+'"></label><label><span>Unit</span><input name="uom" value="'+esc(part.uom||'ea')+'"></label>'+badge(part)+'</div></div><aside class="s80-record-qr">'+qr+'<strong>'+esc(part.code)+'</strong><small>Scan part record</small></aside></section><nav class="s80-tabs">'+tabs.map(([id,label])=>'<button type="button" class="'+(ui.s80SupplyTab===id?'active':'')+'" data-s80-tab="'+id+'"'+(ui.s80SupplyTab===id?' aria-current="page"':'')+'>'+label+'</button>').join('')+'</nav><main class="s80-tab-content" data-s80-tab-content>'+tabContent(part)+'</main></form></div>';
  }
  const renderSupplies=()=>ui.s80SupplyMode==='record'?recordPage(getPart(ui.selectedPart)):listPage();
  renderInventory=renderSupplies;window.renderInventory=renderSupplies;renderPartDetail=recordPage;window.renderPartDetail=recordPage;

  function saveRecord(id,close){
    const part=getPart(id),form=document.querySelector('[data-s80-record-form="'+CSS.escape(String(id))+'"]');if(!part||!form)return;const data=new FormData(form),code=String(data.get('code')||'').trim(),name=String(data.get('name')||'').trim();
    if(!code||!name){toast('Part name and code are required');return}if(a(state.parts).some(item=>item.id!==part.id&&String(item.code).toLowerCase()===code.toLowerCase())){toast('That part code already exists');return}
    const set=key=>{if(data.has(key))part[key]=String(data.get(key)||'').trim()};['name','description','code','category','uom','account','chargeDepartment','inventoryCode','unspscCode','barcode','manufacturer','model','notes'].forEach(set);if(data.has('lastPrice')){part.lastPrice=Number(data.get('lastPrice')||0);part.unitCost=part.lastPrice}if(data.has('preferredBusinessId'))part.preferredBusinessId=String(data.get('preferredBusinessId')||'');addAudit('PART_UPDATED',part.id,part.code+' · '+part.name);saveState();toast('Part / supply saved');if(close)ui.s80SupplyMode='list';render();
  }
  function duplicate(id){const source=getPart(id);if(!source)return;const copy=JSON.parse(JSON.stringify(source));copy.id=uid('PRT');copy.code=source.code+'-COPY';copy.name=source.name+' copy';copy.locations=[];state.parts.push(copy);ui.selectedPart=copy.id;addAudit('PART_DUPLICATED',copy.id,'Copied from '+source.code);saveState();render();toast('Duplicate part created')}
  function printTag(part){if(!part)return;const qr=window.SafiQR?SafiQR.svg('SM:P:'+part.id+':'+part.code,part.code):'',popup=window.open('','_blank','width=520,height=640');if(!popup){toast('Allow pop-ups to print the tag');return}popup.opener=null;popup.document.write('<!doctype html><title>'+esc(part.code)+' tag</title><style>body{font:16px Arial;display:grid;place-items:center;min-height:90vh;color:#10243a}.tag{border:2px solid #10243a;padding:30px;width:300px;text-align:center}.tag svg{width:220px;height:220px}.tag h1{margin:14px 0 6px}.tag p{color:#65798d}@media print{button{display:none}}</style><div class="tag">'+qr+'<h1>'+esc(part.code)+'</h1><strong>'+esc(part.name)+'</strong><p>'+esc(part.category||'Part / supply')+'</p><button onclick="print()">Print tag</button></div>');popup.document.close()}
  const paintFiles=id=>{const target=document.querySelector('[data-s80-part-file-list="'+CSS.escape(String(id))+'"]');if(target&&window.SafiFileUI?.paint)SafiFileUI.paint('part',id,target)};
  const previousRender=render;render=function(){previousRender.apply(this,arguments);document.body.classList.add('safimaint-supplies-v80');if(ui.route==='inventory'&&ui.s80SupplyMode==='record'&&ui.s80SupplyTab==='files'&&ui.selectedPart)setTimeout(()=>paintFiles(ui.selectedPart),30)};window.render=render;
  document.addEventListener('pointerdown',event=>{
    if(event.target.closest('[data-open-part],[data-s79-open-part],[data-search-part]'))ui.s80SupplyMode='record';
    else if(event.target.closest('[data-route="inventory"]'))ui.s80SupplyMode='list';
  },true);
  document.addEventListener('click',event=>{
    const open=event.target.closest('[data-s80-open-part]');if(open){event.preventDefault();event.stopImmediatePropagation();ui.selectedPart=open.dataset.s80OpenPart;ui.s80SupplyMode='record';ui.s80SupplyTab='stock';render();return}
    if(event.target.closest('[data-s80-back]')){event.preventDefault();event.stopImmediatePropagation();ui.s80SupplyMode='list';render();return}
    const tab=event.target.closest('[data-s80-tab]');if(tab){event.preventDefault();event.stopImmediatePropagation();ui.s80SupplyTab=tab.dataset.s80Tab;render();return}
    const filter=event.target.closest('[data-s80-filter]');if(filter){event.preventDefault();event.stopImmediatePropagation();ui.s80SupplyFilter=filter.dataset.s80Filter;render();return}
    const save=event.target.closest('[data-s80-save]');if(save){event.preventDefault();event.stopImmediatePropagation();saveRecord(save.dataset.s80Save,false);return}
    const close=event.target.closest('[data-s80-save-close]');if(close){event.preventDefault();event.stopImmediatePropagation();saveRecord(close.dataset.s80SaveClose,true);return}
    const copy=event.target.closest('[data-s80-duplicate]');if(copy){event.preventDefault();event.stopImmediatePropagation();duplicate(copy.dataset.s80Duplicate);return}
    const print=event.target.closest('[data-s80-print]');if(print){event.preventDefault();event.stopImmediatePropagation();printTag(getPart(print.dataset.s80Print));return}
    if(event.target.closest('[data-s80-refresh]')){event.preventDefault();event.stopImmediatePropagation();render();toast('Parts list refreshed')}
  },true);
  function filterRows(){const query=String(document.querySelector('[data-s80-list-search]')?.value||'').trim().toLowerCase(),category=document.querySelector('[data-s80-category]')?.value||'';let count=0;document.querySelectorAll('[data-s80-part-row]').forEach(row=>{const show=(!query||row.dataset.search.includes(query))&&(!category||row.dataset.category===category);row.hidden=!show;if(show)count++});const number=document.querySelector('[data-s80-visible-count]');if(number)number.textContent=count;const empty=document.querySelector('[data-s80-no-results]');if(empty)empty.hidden=count!==0}
  document.addEventListener('input',event=>{if(event.target.matches('[data-s80-list-search]')){ui.inventorySearch=event.target.value;filterRows()}},true);
  document.addEventListener('change',event=>{if(event.target.matches('[data-s80-category]'))filterRows();const picker=event.target.closest('[data-s80-part-file]');if(picker&&picker.files?.length){event.stopImmediatePropagation();const files=[...picker.files],id=picker.dataset.s80PartFile;picker.disabled=true;(async()=>{try{for(const file of files)await SafiFiles.add('part',id,file);addAudit('PART_FILES_ADDED',id,files.map(file=>file.name).join(', '));saveState();paintFiles(id);toast(files.length+' file'+(files.length===1?'':'s')+' added')}catch(error){toast(error.message)}finally{picker.value='';picker.disabled=false}})()}},true);
  if(ui.route==='inventory')render();
})();
